SELECT r.id || ' — ни одной задачи' AS detail FROM project_requirements r WHERE r.project_id = $1 AND r.kind = 'FR' AND r.out_of_version = '' AND true AND NOT EXISTS (SELECT 1 FROM task_requirement tr WHERE tr.project_id = r.project_id AND tr.requirement_id = r.id) AND NOT EXISTS (SELECT 1 FROM project_milestone_requirements mr JOIN project_plan_milestones m ON m.project_id = mr.project_id AND m.id = mr.milestone_id AND m.closed <> '' WHERE mr.project_id = r.project_id AND mr.requirement_id = r.id AND EXISTS (SELECT 1 FROM project_requirement_proof pf WHERE pf.project_id = r.project_id AND pf.requirement_id = r.id)) UNION ALL SELECT tr.requirement_id || ' — и в ' || string_agg(tr.task_id, ', и в ' ORDER BY tr.task_id) FROM task_requirement tr JOIN project_requirements r ON r.project_id = tr.project_id AND r.id = tr.requirement_id JOIN project_plan_tasks t ON t.project_id = tr.project_id AND t.id = tr.task_id WHERE tr.project_id = $1 AND r.kind = 'FR' AND t.kind <> 'red' AND true GROUP BY tr.requirement_id HAVING count(DISTINCT tr.task_id) > 1 ORDER BY 1
